INSERT INTO project_baseline (project_id, fiscal_year, generation_gwh, source_id, notes) VALUES ('PRJ-009', 2021, 314.77, 'SRC-011', 'PDF p.45, monthly generation table. Annual total equals the sum of the 12 monthly values (check passed). Monthly values in data/cleaned/plant_generation_monthly.csv. In this table the name and abbreviation columns disagree for three rows; this row is taken by abbreviation UT3A (printed beside the name ''Kulekhani II''). Confirmed by the report text (314.767 GWh) and by the FY2021/22 report (432.832 GWh was 37.51% more than the previous year). Name-matching would give 195.16 GWh, which is Kulekhani I.');
INSERT INTO project_baseline (project_id, fiscal_year, generation_gwh, source_id, notes) VALUES ('PRJ-011', 2023, 88.91, 'SRC-008', 'Annual total only (no monthly table for FY2022/23). Taken from the FY2023/24 report comparison table, PDF p.200 (SRC-008), as the previous-year column. Cross-checks: the table''s printed change of -2.34% reproduces from FY2023/24; the FY2022/23 report text gives the same figure to lower precision.');
